import{_ as a,o as d,c as e,a2 as o}from"./chunks/framework.DGvnA5EY.js";const r="/workbuddy-guide/assets/01-growth-loop.x0ZmAqlf.png",b=JSON.parse('{"title":"第 20 章 自媒体不只是靠努力，而是一条增长闭环","description":"> 内容来源：WorkBuddy 官方指南与社区实战案例整理（非官方，© 本指南作者，保留所有权利） 很多人做自媒体卡在\\"又写又剪又发又看数据\\"，精力全耗在重复劳动，最后断更。这一章 把自媒体拆成一条闭环：选题 → 生产 → 发布 → 看数据 → 反哺选题。WorkBuddy 能在 每一环替你省时间…","frontmatter":{"title":"第 20 章 自媒体不只是靠努力，而是一条增长闭环"},"headers":[],"relativePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 20 章 自媒体不只是靠努力，而是一条增长闭环/index.md","filePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 20 章 自媒体不只是靠努力，而是一条增长闭环/index.md","lastUpdated":1791615980000}'),s={name:"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 20 章 自媒体不只是靠努力，而是一条增长闭环/index.md"};function l(n,t,i,h,p,u){return d(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="第-20-章-自媒体不只是靠努力-而是一条增长闭环" tabindex="-1">第 20 章 自媒体不只是靠努力，而是一条增长闭环 <a class="header-anchor" href="#第-20-章-自媒体不只是靠努力-而是一条增长闭环" aria-label="Permalink to &quot;第 20 章 自媒体不只是靠努力，而是一条增长闭环&quot;">​</a></h1><blockquote><p>内容来源：WorkBuddy 官方指南与社区实战案例整理（非官方，© 本指南作者，保留所有权利）</p></blockquote><p>很多人做自媒体卡在&quot;又写又剪又发又看数据&quot;，精力全耗在重复劳动，最后断更。这一章 把自媒体拆成一条<strong>闭环</strong>：选题 → 生产 → 发布 → 看数据 → 反哺选题。WorkBuddy 能在 每一环替你省时间，让&quot;坚持&quot;变得不那么累——关键不是单次爆款，而是<strong>每周稳定转一圈</strong>。</p><p><img src="'+r+`" alt="一只小黑推着一个首尾相接的环在走，环上标着 选题-生产-发布-数据" loading="lazy"></p><p><em>配图为示意插画，用于帮助理解&quot;增长闭环&quot;，与实际软件界面无关。</em></p><h2 id="一、先想清楚-这条闭环要交付什么" tabindex="-1">一、先想清楚：这条闭环要交付什么 <a class="header-anchor" href="#一、先想清楚-这条闭环要交付什么" aria-label="Permalink to &quot;一、先想清楚：这条闭环要交付什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>要说清什么</th><th>示例</th></tr></thead><tbody><tr><td>目标</td><td>做自媒体为了什么</td><td>建立个人影响力、引流到私域</td></tr><tr><td>受众</td><td>谁看</td><td>对 AI 感兴趣的小白</td></tr><tr><td>材料</td><td>你已有的素材/账号</td><td>过往爆款、行业知识</td></tr><tr><td>格式</td><td>内容形态</td><td>短视频为主、图文为辅</td></tr><tr><td>验收</td><td>怎么判断转得好</td><td>每周稳定更新、涨粉结构改善</td></tr></tbody></table><h2 id="二、先选对-skill-自媒体闭环的组合" tabindex="-1">二、先选对 Skill：自媒体闭环的组合 <a class="header-anchor" href="#二、先选对-skill-自媒体闭环的组合" aria-label="Permalink to &quot;二、先选对 Skill：自媒体闭环的组合&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方式 / Skill</th><th>适合处理</th><th>本章怎么用</th><th>注意点</th></tr></thead><tbody><tr><td><strong>选题 / 内容分析技能</strong></td><td>列热点、做差异化、评分</td><td>选题环节提效</td><td>结果当参考，不盲跟</td></tr><tr><td><strong>写作 / 排版技能</strong></td><td>写稿、配图、排版</td><td>生产环节（见第 11 章）</td><td>事实与口吻你把关</td></tr><tr><td><strong>视频生成（第 19 章）</strong></td><td>出短视频草稿</td><td>生产环节</td><td>生成后人工过一遍</td></tr><tr><td><strong>数据 / 后台技能</strong></td><td>读后台、找涨跌原因</td><td>数据环节</td><td>注意账号安全</td></tr><tr><td><strong>自动化（第一篇第 10 章）</strong></td><td>每周自动复盘</td><td>把&quot;看数据&quot;无人化</td><td>配合推送</td></tr></tbody></table><h2 id="三、四环里-ai-能替你做什么" tabindex="-1">三、四环里 AI 能替你做什么 <a class="header-anchor" href="#三、四环里-ai-能替你做什么" aria-label="Permalink to &quot;三、四环里 AI 能替你做什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>环节</th><th>AI 能替你做</th><th>你把关</th></tr></thead><tbody><tr><td>选题</td><td>列热点/角度、做差异化、评分</td><td>选哪个、定调性</td></tr><tr><td>生产</td><td>写稿、配图、剪视频（见第 19 章）</td><td>事实与口吻</td></tr><tr><td>发布</td><td>排期、写标题/简介</td><td>平台规则、合规</td></tr><tr><td>数据</td><td>读后台、找涨跌原因</td><td>判断下一步</td></tr></tbody></table><h2 id="四、真实可复制提示词" tabindex="-1">四、真实可复制提示词 <a class="header-anchor" href="#四、真实可复制提示词" aria-label="Permalink to &quot;四、真实可复制提示词&quot;">​</a></h2><h3 id="提示词-1-选题评分卡" tabindex="-1">提示词 1｜选题评分卡 <a class="header-anchor" href="#提示词-1-选题评分卡" aria-label="Permalink to &quot;提示词 1｜选题评分卡&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我要做一个关于【AI 工具】的短视频选题，请帮我评估以下 3 个候选：</span></span>
<span class="line"><span>【候选1/2/3 各一句话描述】。</span></span>
<span class="line"><span>从四个维度打分（1-10）：搜索热度、竞争程度、差异化空间、变现潜力。</span></span>
<span class="line"><span>每个维度给一句话理由，最后给 3 个优化后的标题备选。</span></span></code></pre></div><h3 id="提示词-2-每周自动复盘-配合第一篇第-10-章" tabindex="-1">提示词 2｜每周自动复盘（配合第一篇第 10 章） <a class="header-anchor" href="#提示词-2-每周自动复盘-配合第一篇第-10-章" aria-label="Permalink to &quot;提示词 2｜每周自动复盘（配合第一篇第 10 章）&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>创建一个自动化任务：每周一上午，读我自媒体后台导出的数据，</span></span>
<span class="line"><span>总结 3 条涨粉/掉粉原因，给 2 个下周选题建议，推送到我微信。</span></span>
<span class="line"><span>如果数据异常（如单条爆了或跌了），单独标注可能原因。</span></span></code></pre></div><h3 id="提示词-3-标题-简介生成" tabindex="-1">提示词 3｜标题/简介生成 <a class="header-anchor" href="#提示词-3-标题-简介生成" aria-label="Permalink to &quot;提示词 3｜标题/简介生成&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>给这条视频生成 5 个标题（口语、带钩子、不标题党）和 1 句简介，</span></span>
<span class="line"><span>风格参考我的账号调性：【粘贴一段你过往的标题样例】。</span></span></code></pre></div><h2 id="五、执行步骤表" tabindex="-1">五、执行步骤表 <a class="header-anchor" href="#五、执行步骤表" aria-label="Permalink to &quot;五、执行步骤表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>步骤</th><th>WorkBuddy 做什么</th><th>你要确认什么</th></tr></thead><tbody><tr><td>1</td><td>选题评分（提示词 1）</td><td>选中的选题是否真符合你定位</td></tr><tr><td>2</td><td>生产内容（写稿/视频）</td><td>事实、口吻、合规</td></tr><tr><td>3</td><td>排期发布</td><td>平台规则、不违规</td></tr><tr><td>4</td><td>每周自动复盘（提示词 2）</td><td>数据结论是否靠谱、指导了下周</td></tr></tbody></table><h2 id="六、零成本-skill-把-选题评分-固化" tabindex="-1">六、零成本 Skill：把&quot;选题评分&quot;固化 <a class="header-anchor" href="#六、零成本-skill-把-选题评分-固化" aria-label="Permalink to &quot;六、零成本 Skill：把&quot;选题评分&quot;固化&quot;">​</a></h2><p>提示词 1 这种&quot;每次发视频前都做&quot;的需求，用 <code>skill-creator</code> 固化成&quot;选题评分官&quot;技能： 以后丢一个候选主题，它就按四维打分+标题备选出结果，不用每次写长提示词。</p><h2 id="七、实际效果与验收标准" tabindex="-1">七、实际效果与验收标准 <a class="header-anchor" href="#七、实际效果与验收标准" aria-label="Permalink to &quot;七、实际效果与验收标准&quot;">​</a></h2><p><strong>实际效果</strong>：一条每周自动转的飞轮——你只在&quot;选题&quot;和&quot;把关&quot;两个节点出手，其余交给 流水线。转得越久，AI 越懂你的账号。</p><p><strong>验收标准</strong>：</p><ul><li>[ ] 每周稳定更新（不是想到才发、断更）</li><li>[ ] 自动复盘真的发生，且结论帮你调了下周选题</li><li>[ ] 发布内容合规、没踩平台红线</li><li>[ ] 你保留了&quot;选题+把关&quot;两个关键决策权</li></ul><h2 id="八、一个必须记住的坑" tabindex="-1">八、一个必须记住的坑 <a class="header-anchor" href="#八、一个必须记住的坑" aria-label="Permalink to &quot;八、一个必须记住的坑&quot;">​</a></h2><p><strong>平台规则和数据隐私别碰线。</strong> 自动发内容前确认不违规；后台数据导出注意账号安全 （连接器见第一篇第 7 章）。另外，AI 给的&quot;爆款公式&quot;只是参考，盲目跟风反而没个性—— <strong>你的判断才是差异化来源。</strong></p><h2 id="小白说明书" tabindex="-1">小白说明书 <a class="header-anchor" href="#小白说明书" aria-label="Permalink to &quot;小白说明书&quot;">​</a></h2><blockquote><p><strong>增长闭环</strong>：选题→生产→发布→数据→反哺选题，循环往复、越转越准的飞轮。</p><p><strong>复盘</strong>：做完一轮后回看数据，找出&quot;什么有效、什么无效&quot;，指导下次。</p><p><strong>排期</strong>：提前安排好内容在什么时候发，避免想到才发、断更。</p><p><strong>零成本 Skill</strong>：用 skill-creator 把周常选题评分固化成专属技能。</p></blockquote><h2 id="本章任务清单" tabindex="-1">本章任务清单 <a class="header-anchor" href="#本章任务清单" aria-label="Permalink to &quot;本章任务清单&quot;">​</a></h2><ul><li>[ ] 画出你自己的&quot;自媒体四环&quot;，标出哪一环最耗你时间</li><li>[ ] 用提示词 1 给 3 个候选选题打分并选一个</li><li>[ ] 设一个每周自动复盘的自动化任务</li><li>[ ] （进阶）用 skill-creator 把&quot;选题评分官&quot;固化成技能</li></ul><hr><p><em>下一篇：第 21 章——WorkBuddy 也能做 GEO 专家。</em></p><hr><p><em>本指南为第三方非官方整理，版权归作者所有，转载请注明出处。</em></p>`,36)])])}const q=a(s,[["render",l]]);export{b as __pageData,q as default};
